package com.paytrace.timeline;
import com.paytrace.payment.*;import com.paytrace.state.*;import org.junit.jupiter.api.*;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class CanonicalStateResolverTest {@Test void ordersByOccurredTimeNotArrivalTime(){var now=Instant.now();var resolver=new CanonicalStateResolver(new PaymentStateMachine());var id=UUID.randomUUID();var settled=new PaymentEventEntity(id,PaymentEventType.PAYMENT_SETTLED,EventSource.WEBHOOK,now.plusSeconds(2),null,null,"{}");var captured=new PaymentEventEntity(id,PaymentEventType.PROVIDER_CAPTURED,EventSource.WEBHOOK,now.plusSeconds(1),null,null,"{}");var authorised=new PaymentEventEntity(id,PaymentEventType.PROVIDER_AUTHORIZED,EventSource.WEBHOOK,now,null,null,"{}");var r=resolver.resolve(List.of(settled,captured,authorised));assertThat(r.canonicalState()).isEqualTo(PaymentState.SETTLED);assertThat(r.anomalies()).contains("OUT_OF_ORDER_DELIVERY");}}
